import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only processing fee)");
    it.todo("plain sword for newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("amulet, staff and potion use their base premiums (60/80/40 G)");
  });

  describe("quote — components and building blocks", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (different types, no block)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword + plain amulet → curse surcharge only on sword: 210 G before policy modifiers and fee");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
    it.todo("cursed sword with enchantment 5 → both curse and high-enchantment surcharges apply");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → loyalty discount applies");
    it.todo("second quote in scenario → 15 % follow-up discount");
    it.todo("newcomer with cursed steel sword (enchantment 3) → 165 G");
    it.todo("3-year customer's second quote, cursed sword enchantment 7 → 160 G (first insurance still applies)");
  });

  describe("quote — rounding", () => {
    it.todo("premium yielding a fraction (e.g. 197.5 G) is rounded up");
  });

  describe("claim — reimbursement", () => {
    it.todo("regular steel sword enchantment 3, damage 500 G → payout 400 G");
    it.todo("rune damage 200 G → payout 100 G");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % clause)");
    it.todo("dragon sword enchantment 5, damage 800 G → payout 700 G");
    it.todo("dragon sword enchantment 9, damage 1000 G → payout 400 G (50 % wins)");
    it.todo("dragon sword exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("payout yielding a fraction (e.g. 350.5 G) is rounded down");
  });

  describe("claim — deductible and cap", () => {
    it.todo("dragon attack damaging sword (500) and amulet (300) → payout 600 G, deductible per item");
    it.todo("sword + amulet policy → cap 3200 G reported as remaining cap");
    it.todo("cursed sword → cap 2000 G, based on unmodified insurance value");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G");
    it.todo("two swords, both damaged → each damage with own deductible, cap 4000 G");
    it.todo("two successive 1500 G claims on a sword → 1400/600 then 600/0");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type → rejected");
    it.todo("claim for item not part of policy → rejected");
    it.todo("claim with unknown item type → rejected");
    it.todo("claim with negative amount → rejected");
    it.todo("claim with more damages of a type than insured → whole claim rejected");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes results JSON to stdout");
    it.todo("exits non-zero and writes error to stderr for invalid scenario, no results on stdout");
  });
});

