const PROCESSING_FEE = 5;
const COMPONENT_BASE_PREMIUM = 25;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE = 0.1;

export const policyBasePremium = (items: Item[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  const listPremium = items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0);
  const blockSavings = BLOCK_SIZE * COMPONENT_BASE_PREMIUM - BLOCK_BASE_PREMIUM;
  const formsBlock = runeCount === BLOCK_SIZE;
  return formsBlock ? listPremium - blockSavings : listPremium;
};

const quotePremium = (items: Item[]): number => {
  const policyBase = policyBasePremium(items);
  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const step = scenario.steps[0] as { op: "quote"; items: Item[] };
  return { results: [{ premium: quotePremium(step.items) }] };
};

