export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const { yearsWithMHPCO } = scenario.customer;
  const results = scenario.steps.map((step, index): Result => {
    if (step.op === "claim") {
      const insuredItems = (scenario.steps[step.policy] as QuoteStep).items;
      return { payout: claimPayout(step.incident.damages, insuredItems), remainingCap: 0 };
    }
    const isFollowUp = scenario.steps.slice(0, index).some((earlier) => earlier.op === "quote");
    return { premium: quotePremium((step as QuoteStep).items, yearsWithMHPCO, isFollowUp) };
  });
  return { results };
};

